// Header CORS wajib untuk Stremio / Nuvio
app.use((req, res, next) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Headers', '*');
    next();
});

// Endpoint Proxy menggunakan modul asal Node.js (tiada npm install diperlukan)
app.get('/proxy', (req, res) => {
    const targetUrl = req.query.url;
    if (!targetUrl) {
        return res.status(400).send('URL tidak disertakan');
    }

    const client = targetUrl.startsWith('https') ? https : http;

    const proxyReq = client.get(targetUrl, {
        headers: {
            Range: req.headers.range || 'bytes=0-'
        }
    }, (proxyRes) => {
        res.writeHead(proxyRes.statusCode, {
            'Content-Type': proxyRes.headers['content-type'] || 'video/mp4',
            'Content-Length': proxyRes.headers['content-length'],
            'Accept-Ranges': 'bytes',
            'Content-Range': proxyRes.headers['content-range']
        });

        proxyRes.pipe(res);
    });

    proxyReq.on('error', (error) => {
        console.error('Ralat Proxy:', error.message);
        res.status(500).send('Gagal memuat turun strim video.');
    });
});

// 1. Endpoint Manifest Addon
app.get('/manifest.json', (req, res) => {
    res.json({
        id: 'org.nuviotelegramaddon',
        version: '1.0.0',
        name: 'Running Man Telegram Addon',
        description: 'Addon Stremio untuk koleksi video Running Man',
        types: ['series'],
        catalogs: [
            {
                type: 'series',
                id: 'running_man_catalog',
                name: 'Running Man Telegram'
            }
        ],
        resources: ['catalog', 'meta', 'stream']
    });
});

// 2. Endpoint Catalog
app.get('/catalog/:type/:id.json', (req, res) => {
    const metas = catalogData.map(item => ({
        id: item.id,
        type: item.type,
        name: item.name,
        poster: item.poster,
        description: item.description
    }));
    res.json({ metas });
});

// 3. Endpoint Meta
app.get('/meta/:type/:id.json', (req, res) => {
    const { id } = req.params;
    const series = catalogData.find(item => item.id === id);
    
    if (!series) {
        return res.status(404).json({ error: "Not found" });
    }

    res.json({
        meta: {
            id: series.id,
            type: series.type,
            name: series.name,
            poster: series.poster,
            description: series.description,
            videos: series.videos.map(v => ({
                id: v.id,
                title: v.title,
                episode: v.episode,
                overview: v.description
            }))
        }
    });
});

// 4. Endpoint Stream
app.get('/stream/:type/:id.json', (req, res) => {
    const { id } = req.params;
    
    for (const series of catalogData) {
        const video = series.videos.find(v => v.id === id);
        if (video) {
            return res.json({ streams: video.streams });
        }
    }
    
    res.json({ streams: [] });
});

app.get('/', (req, res) => {
    res.send('Running Man Stremio Addon Proxy Server is running!');
});

app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
